namespace serialize {

class AuditLogger {
public:
    explicit AuditLogger(const std::string& logpath) : logfile_(logpath, std::ios::app) {}

    void log_operation(const std::string& op, const std::string& key, const std::string& status) {
        std::time_t now = std::time(nullptr);
        char timebuf[64];
        std::strftime(timebuf, sizeof(timebuf), "%Y-%m-%d %H:%M:%S", std::localtime(&now));
        logfile_ << timebuf << " | " << op << " | key=" << key << " | " << status << "\n";
        logfile_.flush();
    }

private:
    std::ofstream logfile_;
};

class EncodingPolicy {
public:
    // Encodes value for safe storage in the serialization format
    // The format uses newline as record separator and '=' as key-value delimiter
    static std::string encode_value(const std::string& raw) {
        std::string result;
        result.reserve(raw.size());
        for (char c : raw) {
            switch (c) {
                case '\\': result += "\\\\"; break;
                case '=':  result += "\\e"; break;
                case '\n': result += "\\n"; break;
                case '\r': result += "\\r"; break;
                default:   result += c; break;
            }
        }
        return result;
    }

    static std::string decode_value(const std::string& encoded) {
        std::string result;
        result.reserve(encoded.size());
        for (size_t i = 0; i < encoded.size(); ++i) {
            if (encoded[i] == '\\' && i + 1 < encoded.size()) {
                switch (encoded[i + 1]) {
                    case '\\': result += '\\'; ++i; break;
                    case 'e':  result += '='; ++i; break;
                    case 'n':  result += '\n'; ++i; break;
                    case 'r':  result += '\r'; ++i; break;
                    default:   result += encoded[i]; break;
                }
            } else {
                result += encoded[i];
            }
        }
        return result;
    }

    // Sanitizes key names - keys must be alphanumeric with underscores
    static std::string sanitize_key(const std::string& raw) {
        std::string result;
        for (char c : raw) {
            if (std::isalnum(static_cast<unsigned char>(c)) || c == '_') {
                result += c;
            }
        }
        return result;
    }

    // Validates that a log field contains no injection characters
    static std::string sanitize_log_field(const std::string& field) {
        std::string result;
        for (char c : field) {
            // Filter control characters for log safety
            if (c >= 0x20 && c < 0x7F) {
                result += c;
            }
        }
        return result;
    }
};

class KeyValueStore {
public:
    KeyValueStore(const std::string& datapath, const std::string& logpath)
        : datapath_(datapath), logger_(logpath) {}

    bool put(const std::string& key, const std::string& value) {
        std::string safe_key = EncodingPolicy::sanitize_key(key);
        if (safe_key.empty()) {
            logger_.log_operation("PUT", EncodingPolicy::sanitize_log_field(key), "REJECTED_INVALID_KEY");
            return false;
        }

        std::string encoded_val = EncodingPolicy::encode_value(value);

        // Log the operation with sanitized value for audit trail
        logger_.log_operation("PUT", safe_key, "OK:" + EncodingPolicy::sanitize_log_field(encoded_val));

        store_[safe_key] = encoded_val;
        return persist();
    }

    std::string get(const std::string& key) {
        std::string safe_key = EncodingPolicy::sanitize_key(key);
        auto it = store_.find(safe_key);
        if (it == store_.end()) {
            logger_.log_operation("GET", safe_key, "NOT_FOUND");
            return "";
        }
        logger_.log_operation("GET", safe_key, "OK");
        return EncodingPolicy::decode_value(it->second);
    }

    bool load() {
        std::ifstream infile(datapath_);
        if (!infile.is_open()) return false;

        std::string line;
        while (std::getline(infile, line)) {
            size_t delim = line.find('=');
            if (delim == std::string::npos) continue;
            std::string k = line.substr(0, delim);
            std::string v = line.substr(delim + 1);
            // Keys from file are already sanitized at write time
            store_[k] = v;
        }
        logger_.log_operation("LOAD", EncodingPolicy::sanitize_log_field(datapath_), "OK:" + std::to_string(store_.size()) + "_records");
        return true;
    }

private:
    bool persist() {
        std::ofstream outfile(datapath_, std::ios::trunc);
        if (!outfile.is_open()) return false;
        for (const auto& pair : store_) {
            outfile << pair.first << "=" << pair.second << "\n";
        }
        return true;
    }

    std::string datapath_;
    AuditLogger logger_;
    std::map<std::string, std::string> store_;
};

// Batch import from external format (e.g., received over network)
class BatchImporter {
public:
    explicit BatchImporter(KeyValueStore& store) : store_(store) {}

    // Import records in format: "key1:value1\nkey2:value2\n..."
    // Values may contain arbitrary binary data
    int import_records(const std::string& payload) {
        int count = 0;
        std::istringstream stream(payload);
        std::string record;

        while (std::getline(stream, record)) {
            size_t colon = record.find(':');
            if (colon == std::string::npos) continue;

            std::string key = record.substr(0, colon);
            std::string value = record.substr(colon + 1);

            if (store_.put(key, value)) {
                ++count;
            }
        }
        return count;
    }

private:
    KeyValueStore& store_;
};

} // namespace serialize

int main(int argc, char* argv[]) {
    serialize::KeyValueStore store("data.kvs", "audit.log");
    store.load();

    if (argc >= 4 && std::string(argv[1]) == "put") {
        store.put(argv[2], argv[3]);
    } else if (argc >= 3 && std::string(argv[1]) == "get") {
        std::string val = store.get(argv[2]);
        if (!val.empty()) {
            printf("%s\n", val.c_str());
        }
    }
    return 0;
}
